# «من أصحابه ﷺ» — الدفعة 2 (2026-11-20، اختياري بعد أن ترك المستخدم لي الخيار): python3 data/ahl/batch2.py
# 19 صحابيًّا جديدًا؛ كل جملة تحقّقتُ منها في نسخ fawazahmed0 (scratchpad/hj/f.py) أو فتح الباري (OpenITI)،
# وفحصتُها مقابل نصوص البطاقات ومتونها وشروحها وأقوال «قالوا عنه» حتى لا تتكرّر.
# بعد موافقة المستخدم تُنقل إلى data/ahl/batch1.json (build.py) ثم export.py فتصل في public/lines.json بلا تحديث.
import json
SB='صحيح — البخاري'; SM='صحيح — مسلم'; SBM='صحيح — البخاري ومسلم'; S='من أصحابه ﷺ'
E=[
('S18','عبد الرحمن بن عوف، عرض عليه أخوه الأنصاري نصف ماله، فقال: «بارك الله لك في أهلك ومالك، دلّوني على السوق».','البخاري 2049',SB,'قال بارك الله لك في أهلك ومالك، دلوني على السوق',''),
('S19','سعيد بن زيد، أحد العشرة الذين بشّرهم ﷺ بالجنة.','الترمذي 3757','صحيح — قال الترمذي: حسن صحيح','قيل فمن العاشر قال أنا','رقم الحديث في نسخة fawazahmed0، ويُراجَع في sunnah.com قبل النشر (قد يكون 3748).'),
('S20','أبو ذر الغفاري، قال ﷺ: «ما أظلّت الخضراء ولا أقلّت الغبراء من ذي لهجة أصدق ولا أوفى من أبي ذر»؛ أي: ما على الأرض أصدق لسانًا منه.','الترمذي 3802','حسن — الترمذي','ما أظلت الخضراء ولا أقلت الغبراء من ذي لهجة أصدق ولا أوفى من أبي ذر','قال الترمذي: حسن غريب؛ لم أراجع حكم غيره بعد.'),
('S21','سلمان الفارسي، من رامَهُرمُز ببلاد فارس، خرج يطلب الدين الحق، فتنقّل بين أكثر من عشرة أسياد حتى بلغ النبي ﷺ.','البخاري 3946 و3947، وفتح الباري 7/277',SB,'أنه تداوله بضعة عشر من رب إلى رب … أنا من رام هرمز','قال ابن حجر: «أي من سيد إلى سيد»، وذكر أنه خرج في طلب الدين؛ أي: بيع عبدًا وانتقل من سيّد إلى سيّد. بدّلتُ حديث الثريا بطلبك.'),
('S22','خالد بن الوليد، أخذ الراية يوم مؤتة ففتح الله على يديه، فسمّاه ﷺ «سيفًا من سيوف الله».','البخاري 4262، وفتح الباري 7/513',SB,'حتى أخذ الراية سيف من سيوف الله حتى فتح الله عليهم','الاسم ليس في لفظ البخاري؛ قال ابن حجر: «فإن المراد به خالد ومن يومئذ تسمّى سيف الله».'),
('S23','عبد الله بن عباس، ضمّه ﷺ إليه وقال: «اللهم علّمه الكتاب».','البخاري 75',SB,'ضمني رسول الله صلى الله عليه وسلم وقال اللهم علمه الكتاب',''),
('S24','سعد بن معاذ، قال ﷺ حين مات: «اهتزّ العرش لموت سعد بن معاذ».','البخاري 3803، ومسلم 2466',SBM,'اهتز العرش لموت سعد بن معاذ',''),
('S25','مصعب بن عمير، قُتل يوم أحد ولم يترك إلا ثوبًا، إذا غُطّي به رأسه بدت رجلاه.','البخاري 1276، ومسلم 940',SBM,'منهم مصعب بن عمير قتل يوم أحد فلم يوجد له شيء يكفن فيه إلا نمرة فكنا إذا وضعناها على رأسه خرجت رجلاه',''),
('S26','أبو موسى الأشعري، قال له ﷺ: «لقد أوتيتَ مزمارًا من مزامير آل داود»؛ أي: صوتًا حسنًا بالقرآن.','البخاري 5048، ومسلم 793',SBM,'يا أبا موسى لقد أوتيت مزمارا من مزامير آل داود',''),
('S27','عبد الله بن سلام، كان من علماء اليهود، فسأله ﷺ عن ثلاث «لا يعلمهنّ إلا نبي»، فلما أجابه أسلم.','البخاري 3329',SB,'إني سائلك عن ثلاث لا يعلمهن إلا نبي','KA02 عن وجهه ﷺ «ليس بوجه كذّاب»، وهذا خبر آخر.'),
('S28','ثابت بن قيس، كان عالي الصوت، فلما نزل النهي عن رفع الصوت فوق صوت النبي ﷺ ظنّ أن عمله ضاع، فبشّره ﷺ: «إنك لستَ من أهل النار، ولكن من أهل الجنة».','البخاري 3613',SB,'كان يرفع صوته فوق صوت النبي صلى الله عليه وسلم فقد حبط عمله … فقل له إنك لست من أهل النار ولكن من أهل الجنة','أوضحتُ القصة بطلبك، وغيّرتُ المصدر إلى لفظ البخاري.'),
('S29','عُكّاشة بن محصن، سأله أن يدعو له ليكون من السبعين ألفًا الذين يدخلون الجنة بلا حساب، فقال ﷺ: «اللهم اجعله منهم».','البخاري 6541، ومسلم 216',SBM,'فقام إليه عكاشة بن محصن فقال ادع الله أن يجعلني منهم قال اللهم اجعله منهم',''),
('S30','أسماء بنت أبي بكر، «ذات النطاقين»: شقّت نطاقها نصفين، ربطت بهما طعام النبي ﷺ وسقاءه ليلة الهجرة.','البخاري 2979',SB,'فشقيه باثنين، فاربطيه بواحد السقاء وبالآخر السفرة، ففعلت، فلذلك سميت ذات النطاقين','النطاق: حزام تشدّه المرأة على وسطها. HB39 عنها خبر آخر (صلة أمها).'),
('S31','أبو قتادة وسلمة بن الأكوع، قال ﷺ: «كان خير فرساننا اليوم أبو قتادة، وخير رجّالتنا سلمة»؛ أي: خير المشاة.','مسلم 1807',SM,'كان خير فرساننا اليوم أبو قتادة وخير رجالتنا سلمة',''),
('S32','حسان بن ثابت، قال له ﷺ: «إنّ روح القدس لا يزال يؤيّدك ما نافحتَ عن الله ورسوله»؛ أي: ما دافعت.','مسلم 2490',SM,'إن روح القدس لا يزال يؤيدك ما نافحت عن الله ورسوله','روح القدس: جبريل عليه السلام. أبيات حسان QA18 وQA20 في «قالوا عنه».'),
('S33','البراء بن مالك، قال ﷺ: «كم من أشعث أغبر لا يُؤبه له، لو أقسم على الله لأبرّه، منهم البراء بن مالك».','الترمذي 3854','حسن — الترمذي','كم من أشعث أغبر ذي طمرين لا يؤبه له لو أقسم على الله لأبره منهم البراء بن مالك','قال الترمذي: حسن غريب؛ حُذفت «ذي طمرين» (ثوبين باليين) للاختصار، وأُضيف «…» إن أردت.'),
('S34','عمار بن ياسر، أجاره الله من الشيطان على لسان نبيه ﷺ.','البخاري 3287',SB,'أفيكم الذي أجاره الله من الشيطان على لسان نبيه … يعني عمارا','من قول أبي الدرداء، والتفسير «يعني عمارًا» في رواية البخاري نفسها.'),
]
out=[dict(id=i,head=S,cat='أصحابه',text=t,source=s,grade=g,origin=o,note=nt) for i,t,s,g,o,nt in E]
for x in out: assert len(x['text'])<=150, (x['id'],len(x['text']))
json.dump({'version':1,'lines':out},open('data/ahl/batch2.json','w'),ensure_ascii=False,indent=1)
print(len(out),'max',max(len(x['text']) for x in out))
